// SPDX‑License‑Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/AccessControl.sol";

contract DeviceRegistry is AccessControl {
    bytes32 public constant GATEWAY_ROLE = keccak256("GATEWAY_ROLE");

    struct DeviceInfo {
        address owner;          // who registered the device
        string  deviceId;       // "DEV‑001"
        string  fwVersion;      // current firmware
        uint256 lastUpdated;    // timestamp
    }

    mapping(string => DeviceInfo) private _devices;  // id → info
    string[] private _deviceIndex;

    /* events */
    event DeviceRegistered(string indexed deviceId, address owner);
    event DeviceRemoved   (string indexed deviceId);
    event DeviceStatusUpdated(string indexed deviceId, string fwVersion);

    constructor(address admin, address gateway) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(GATEWAY_ROLE,       gateway);
    }

    /* registration -------------------------------------------------------- */

    function registerDevice(string calldata deviceId) external {
        require(_devices[deviceId].owner == address(0), "exists");

        _devices[deviceId] = DeviceInfo(
            msg.sender,
            deviceId,
            "0x0000",
            block.timestamp
        );
        _deviceIndex.push(deviceId);

        emit DeviceRegistered(deviceId, msg.sender);
    }

    function removeDevice(string calldata deviceId) external {
        DeviceInfo memory d = _devices[deviceId];
        require(
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender) || d.owner == msg.sender,
            "no permission"
        );
        delete _devices[deviceId];
        emit DeviceRemoved(deviceId);
    }

    /* status update ------------------------------------------------------- */

    function updateDeviceStatus(
        string calldata deviceId,
        string calldata fwVersion
    ) external onlyRole(GATEWAY_ROLE) {
        DeviceInfo storage d = _devices[deviceId];
        require(d.owner != address(0), "not found");

        d.fwVersion   = fwVersion;
        d.lastUpdated = block.timestamp;

        emit DeviceStatusUpdated(deviceId, fwVersion);
    }

    /* views --------------------------------------------------------------- */

    function getDevice(string calldata deviceId)
        external
        view
        returns (DeviceInfo memory)
    {
        return _devices[deviceId];
    }

    function getAllDevices()
        external
        view
        returns (DeviceInfo[] memory list)
    {
        uint256 n = _deviceIndex.length;
        list = new DeviceInfo[](n);
        for (uint256 i; i < n; ++i) {
            list[i] = _devices[_deviceIndex[i]];
        }
    }
}
